int result = LFS_CMP_EQ;
lfs_size_t size_left = size;
lfs_off_t offset = off;
while (size_left > 0) {
    lfs_size_t to_read = lfs_min(lfs_min(size_left, hint), lfs->block_size - offset);
    uint8_t *read_buffer = static_cast<uint8_t*>(std::malloc(to_read));
    if (lfs->cfg->read(lfs, block, offset, read_buffer, to_read) < 0) {
        result = LFS_ERR_IO;
        break;
    }
    if (std::memcmp(read_buffer, static_cast<const uint8_t*>(buffer), to_read) != 0) {
        result = (std::memcmp(read_buffer, static_cast<const uint8_t*>(buffer), to_read) < 0) ? LFS_CMP_LT : LFS_CMP_GT;
        break;
    }
    std::free(read_buffer);
    size_left -= to_read;
    offset += to_read;
    if (offset == lfs->block_size) {
        offset = 0;
        block++;
    }
    buffer = static_cast<const void*>(static_cast<const uint8_t*>(buffer) + to_read);
}
return result;

